# MeterReading: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Meterreading:
    meter_id: str = None  # Meter ID
    timestamp: str = None  # ISO 8601
    kwh: float = None  # kWh consumed
    kw_peak: float = None  # Peak kW
    voltage_v: float = None  # Volts

REQUIRED = ["meter_id", "timestamp", "kwh", "kw_peak"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'meter_id': 'MTR-88412', 'timestamp': '2026-07-01T14:00:00Z', 'kwh': 2.41, 'kw_peak': 3.8, 'voltage_v': 241}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

